import{_ as e,o as i,c as a,ae as l}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"Bill Splitting","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/guide/09-bill-split-guide.md","filePath":"v1/en/guide/09-bill-split-guide.md"}'),o={name:"v1/en/guide/09-bill-split-guide.md"};function s(n,t,r,u,h,d){return i(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="bill-splitting" tabindex="-1">Bill Splitting <a class="header-anchor" href="#bill-splitting" aria-label="Permalink to &quot;Bill Splitting&quot;">​</a></h1><h2 id="_1-what-this-feature-is" tabindex="-1">1. What this feature is <a class="header-anchor" href="#_1-what-this-feature-is" aria-label="Permalink to &quot;1. What this feature is&quot;">​</a></h2><p>When a single purchase covers multiple purposes (for example, a “grocery” purchase that includes fruit and household items), you can split one bill into multiple sub-bills so category statistics are more accurate.</p><p>After splitting:</p><ul><li>You will see multiple “sub-bills” (each with its own category, amount, and note).</li><li>The original bill becomes a “split container” and is excluded from the list and totals to avoid double counting.</li></ul><h2 id="_2-when-to-use-it" tabindex="-1">2. When to use it <a class="header-anchor" href="#_2-when-to-use-it" aria-label="Permalink to &quot;2. When to use it&quot;">​</a></h2><ul><li>One payment includes multiple categories (food + daily essentials, transport + parking, etc.)</li><li>You want more granular category stats or budget comparisons</li><li>You want to allocate one receipt across different categories/tags</li></ul><h2 id="_3-how-to-use-it" tabindex="-1">3. How to use it <a class="header-anchor" href="#_3-how-to-use-it" aria-label="Permalink to &quot;3. How to use it&quot;">​</a></h2><ol><li>Open the bill list and find the bill you want to split</li><li>Swipe left on the bill and select <strong>Split</strong></li><li>On the <strong>Split Bill</strong> page: <ul><li>Tap <strong>Category</strong> to choose a category for each sub-item</li><li>Tap <strong>Amount</strong> to enter the amount for each sub-item</li><li>Notes are optional (for additional context)</li><li>Tap <strong>Add Item</strong> if you need more rows</li></ul></li><li>Make sure <strong>Remaining amount to allocate</strong> is 0 (the sum of sub-items matches the original amount)</li><li>Tap <strong>Done/Save</strong> in the top-right corner</li></ol><h2 id="_4-rules-and-notes" tabindex="-1">4. Rules and notes <a class="header-anchor" href="#_4-rules-and-notes" aria-label="Permalink to &quot;4. Rules and notes&quot;">​</a></h2><ul><li>The sum of sub-item amounts must equal the original bill amount; otherwise you can’t save.</li><li>Each sub-item must have a category and an amount greater than 0.</li><li>Statistics are calculated from sub-bills; the original bill is not included.</li><li>Multi-level splitting is supported: a sub-bill can be split again. Totals are calculated from the final (leaf) sub-bills.</li><li>Bill splitting and reimbursements are mutually exclusive: expenses marked as reimbursable/pending reimbursed/reimbursed can’t be split; bills that have been split can’t start the reimbursement flow. Decide whether the expense needs reimbursement first, then choose whether to split it.</li></ul><h2 id="_5-faq" tabindex="-1">5. FAQ <a class="header-anchor" href="#_5-faq" aria-label="Permalink to &quot;5. FAQ&quot;">​</a></h2><h3 id="q1-where-did-the-original-bill-go-after-splitting" tabindex="-1">Q1: Where did the original bill go after splitting? <a class="header-anchor" href="#q1-where-did-the-original-bill-go-after-splitting" aria-label="Permalink to &quot;Q1: Where did the original bill go after splitting?&quot;">​</a></h3><p>To prevent double counting, the original bill is marked as a “split container” and typically won’t appear in the list. Statistics are calculated from the sub-bills.</p><h3 id="q2-can-i-split-only-part-of-the-bill" tabindex="-1">Q2: Can I split only part of the bill? <a class="header-anchor" href="#q2-can-i-split-only-part-of-the-bill" aria-label="Permalink to &quot;Q2: Can I split only part of the bill?&quot;">​</a></h3><p>Yes. You can keep one line as “Other / original category” and set its amount to the remainder. The key requirement is that the sub-item totals equal the original amount.</p><h3 id="q3-can-i-edit-it-after-splitting" tabindex="-1">Q3: Can I edit it after splitting? <a class="header-anchor" href="#q3-can-i-edit-it-after-splitting" aria-label="Permalink to &quot;Q3: Can I edit it after splitting?&quot;">​</a></h3><p>In most cases, it’s best to edit the sub-bills directly (amount/category/note). If you need to re-split, a common approach is to delete the related sub-bills and split again.</p>',18)])])}const b=e(o,[["render",s]]);export{p as __pageData,b as default};
